package xyz.d1n0.ui.text

import androidx.compose.runtime.Composable
import org.jetbrains.compose.resources.StringResource
import org.jetbrains.compose.resources.getString
import org.jetbrains.compose.resources.stringResource
import xyz.d1n0.lib.model.HomeTimezone
import xyz.d1n0.lib.model.Timezone
import xyz.d1n0.lib.model.WorldTimezone
import xyz.d1n0.resources.*

// The city names the app shows. They come from home_timezones.xml and world_timezones.xml,
// generated by the scripts in data/, and are only for display: what the watch shows and is sent,
// Timezone.cityName and cityCode, is never translated.

/**
 * Key of the city's name in home_timezones.xml or world_timezones.xml, e.g. home_tz_30000, null for
 * another kind of time zone.
 */
internal val Timezone.cityNameKey: String?
	get() = when (this) {
		is HomeTimezone -> "home_tz_$identifier"
		is WorldTimezone -> "world_tz_$identifier"
		else -> null
	}

private val Timezone.cityNameResource: StringResource?
	get() = cityNameKey?.let { Res.allStringResources[it] }

/** For a time zone without a generated name, e.g. a new one before the scripts ran again. */
private val Timezone.fallbackCity: String
	get() = when (this) {
		is WorldTimezone -> city
		else -> cityName.lowercase().replaceFirstChar { it.uppercase() }
	}

/** The city's name in the user's language, the English name if it has no translation. */
val Timezone.displayCity: String
	@Composable get() = cityNameResource?.let { stringResource(it) } ?: fallbackCity

/** [displayCity] outside composition, e.g. to search all time zones. */
suspend fun Timezone.loadDisplayCity(): String = cityNameResource?.let { getString(it) } ?: fallbackCity
